mapper.select:
SELECT c.copywriting_id, c.title, c.content, c.create_time, c.create_by FROM t_copywriting c JOIN t_copywriting_approval_flow f ON c.copywriting_id = f.copywriting_id WHERE f.current_status = 1
AND c.title LIKE CONCAT('%', #{submitterName}, '%')
ORDER BY c.create_time DESC LIMIT #{start}, #{pageSize}

SELECT c.copywriting_id, c.title, c.content, c.create_time, c.create_by FROM t_copywriting c JOIN t_copywriting_approval_flow f ON c.copywriting_id = f.copywriting_id WHERE f.current_status = 3
AND c.title LIKE CONCAT('%', #{submitterName}, '%')
ORDER BY c.create_time DESC LIMIT #{start}, #{pageSize}
